CREATE TABLE IF NOT EXISTS LShufWork_Shape (LeaderType TEXT PRIMARY KEY, Ability TEXT, Modded INTEGER, NMods INTEGER, Whole INTEGER, Changed INTEGER, HasRest INTEGER, WholeValue INTEGER);
DELETE FROM LShufWork_Shape;
  FROM LShufWork_Pool p JOIN LShufWork_L l ON l.LeaderType = p.LeaderType WHERE p.Axis = 'A' AND (SELECT IsSplit FROM LShufWork_Cfg) = 1;
UPDATE LShufWork_Shape SET Changed = (Modded = 1 AND (NOT EXISTS (SELECT 1 FROM LShufReviewedSets r WHERE r.AbilityTrait = LShufWork_Shape.Ability)
    OR length((SELECT r.ModifierSet FROM LShufReviewedSets r WHERE r.AbilityTrait = LShufWork_Shape.Ability)) - length(replace((SELECT r.ModifierSet FROM LShufReviewedSets r WHERE r.AbilityTrait = LShufWork_Shape.Ability), '|', '')) - 1 <> NMods
    OR EXISTS (SELECT 1 FROM TraitModifiers tm WHERE tm.TraitType = LShufWork_Shape.Ability AND instr((SELECT r.ModifierSet FROM LShufReviewedSets r WHERE r.AbilityTrait = LShufWork_Shape.Ability), '|' || tm.ModifierId || '|') = 0)));
UPDATE LShufWork_Shape SET Whole = (Changed = 1
  OR NOT EXISTS (SELECT 1 FROM LShufMapping m WHERE m.LeaderType = LShufWork_Shape.LeaderType)
  OR EXISTS (SELECT 1 FROM LShufMapping m WHERE m.LeaderType = LShufWork_Shape.LeaderType
    AND (COALESCE(m.Reviewed, 0) <> 1 OR m.AbilityTrait IS NOT LShufWork_Shape.Ability)));
UPDATE LShufWork_Shape SET WholeValue = CASE WHEN EXISTS (SELECT 1 FROM LShufMapping m WHERE m.LeaderType = LShufWork_Shape.LeaderType AND m.Kind = 'bullet')
  THEN (SELECT SUM(COALESCE(m.Value, 1)) FROM LShufMapping m WHERE m.LeaderType = LShufWork_Shape.LeaderType AND m.Kind = 'bullet') ELSE 5 END;
UPDATE LShufWork_Shape SET HasRest = CASE WHEN Whole = 1 THEN 0 ELSE (
  EXISTS (SELECT 1 FROM LShufMapping m WHERE m.LeaderType = LShufWork_Shape.LeaderType AND m.Kind = 'bullet' AND COALESCE(m.Movable, 1) <> 1)
  OR EXISTS (SELECT 1 FROM TraitModifiers tm WHERE tm.TraitType = LShufWork_Shape.Ability AND tm.ModifierId NOT IN (SELECT mm.ModifierId FROM LShufMappingModifiers mm JOIN LShufMapping m ON m.PieceId = mm.PieceId
      WHERE m.LeaderType = LShufWork_Shape.LeaderType AND ((m.Kind = 'bullet' AND COALESCE(m.Movable, 1) = 1) OR m.Kind = 'agenda')))) END;

CREATE TABLE IF NOT EXISTS LShufWork_Pc (PieceId TEXT PRIMARY KEY, FromLeader TEXT, Kind TEXT, BI INTEGER, Value INTEGER, DV INTEGER, Rank INTEGER, K INTEGER, DeckOrd INTEGER);
DELETE FROM LShufWork_Pc;
  SELECT LeaderType || '__WHOLE', LeaderType, 'whole', 0, WholeValue FROM LShufWork_Shape WHERE Whole = 1;
  SELECT m.PieceId, m.LeaderType, 'bullet', COALESCE(m.BulletIndex, 0), COALESCE(m.Value, 1)
  FROM LShufMapping m JOIN LShufWork_Shape s ON s.LeaderType = m.LeaderType AND s.Whole = 0
  WHERE m.Kind = 'bullet' AND COALESCE(m.Movable, 1) = 1;
CREATE TABLE IF NOT EXISTS LShufWork_BuildTake (PieceId TEXT PRIMARY KEY, Builder TEXT, FromLeader TEXT, Kind TEXT, Value INTEGER);
DELETE FROM LShufWork_BuildTake;
INSERT OR IGNORE INTO LShufWork_BuildTake (PieceId, Builder, FromLeader, Kind, Value)
  SELECT s.LeaderType || '__WHOLE', (SELECT b.Leader FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1), s.LeaderType, 'whole', s.WholeValue
  FROM LShufWork_Shape s WHERE (SELECT b.Leader FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1) IN (SELECT LeaderType FROM LShufWork_Pool WHERE Axis = 'A') AND s.LeaderType IN (SELECT p.Arg FROM LShufWork_BuildPiece p WHERE p.Kind = 'whole' AND p.Slot = 1) AND EXISTS (SELECT 1 FROM LShufWork_Pc c WHERE c.FromLeader = s.LeaderType AND c.PieceId NOT IN (SELECT PieceId FROM LShufWork_BuildTake));
DELETE FROM LShufWork_Pc WHERE FromLeader IN (SELECT FromLeader FROM LShufWork_BuildTake WHERE Kind = 'whole')
  AND PieceId NOT IN (SELECT PieceId FROM LShufWork_BuildTake);
INSERT OR IGNORE INTO LShufWork_Pc (PieceId, FromLeader, Kind, BI, Value) SELECT PieceId, FromLeader, 'whole', 0, Value
  FROM LShufWork_BuildTake WHERE Kind = 'whole' AND Builder = (SELECT b.Leader FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1);
