UPDATE LShufWork_Pc SET DV = CASE WHEN (SELECT Balanced FROM LShufWork_Cfg) = 1 THEN Value ELSE 0 END;
UPDATE LShufWork_Pc SET Rank = (SELECT COUNT(*) FROM LShufWork_Pc o WHERE 1 = 1 AND (o.PieceId < LShufWork_Pc.PieceId)) WHERE 1 = 1;
UPDATE LShufWork_Pc SET K = ((((((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (2) * 104729 + (Rank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (2) * 104729 + (Rank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859) * (((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (2) * 104729 + (Rank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (2) * 104729 + (Rank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859)) + 1664525) % 67108859);
UPDATE LShufWork_Pc SET DeckOrd = (SELECT COUNT(*) FROM LShufWork_Pc o WHERE 1 = 1 AND (o.DV > LShufWork_Pc.DV OR (o.DV = LShufWork_Pc.DV AND (o.K < LShufWork_Pc.K OR (o.K = LShufWork_Pc.K AND (o.PieceId < LShufWork_Pc.PieceId)))))) WHERE 1 = 1;
CREATE TABLE IF NOT EXISTS LShufWork_Slot (LeaderType TEXT PRIMARY KEY, N INTEGER, K INTEGER);
DELETE FROM LShufWork_Slot;
  CASE WHEN s.Whole = 1 THEN 1 ELSE (SELECT COUNT(*) FROM LShufMapping m WHERE m.LeaderType = p.LeaderType AND m.Kind = 'bullet' AND COALESCE(m.Movable, 1) = 1) END, p.K
  FROM LShufWork_Pool p JOIN LShufWork_Shape s ON s.LeaderType = p.LeaderType WHERE p.Axis = 'A' AND (SELECT IsSplit FROM LShufWork_Cfg) = 1
    AND p.LeaderType NOT IN (SELECT Builder FROM LShufWork_BuildTake);
CREATE TABLE IF NOT EXISTS LShufWork_Dealt (PieceId TEXT PRIMARY KEY, LeaderType TEXT, FromLeader TEXT, Value INTEGER);
DELETE FROM LShufWork_Dealt;
CREATE INDEX IF NOT EXISTS LShufWork_Dealt_Leader ON LShufWork_Dealt (LeaderType);
  FROM LShufWork_BuildTake;

DROP VIEW IF EXISTS LShufWork_NextPiece;
CREATE VIEW LShufWork_NextPiece AS SELECT c.PieceId AS PieceId, c.FromLeader AS FromLeader, c.Value AS Value,
  s.LeaderType AS LeaderType
  FROM (SELECT p.PieceId, p.FromLeader, p.Value FROM LShufWork_Pc p
    WHERE NOT EXISTS (SELECT 1 FROM LShufWork_Dealt d WHERE d.PieceId = p.PieceId) ORDER BY p.DeckOrd LIMIT 1) c
  LEFT JOIN LShufWork_Slot s ON (SELECT COUNT(*) FROM LShufWork_Dealt d WHERE d.LeaderType = s.LeaderType) < s.N
  ORDER BY CASE WHEN s.LeaderType = c.FromLeader THEN 1 ELSE 0 END,
    CASE WHEN (SELECT Balanced FROM LShufWork_Cfg) = 1 THEN (COALESCE((SELECT SUM(d.Value) FROM LShufWork_Dealt d WHERE d.LeaderType = s.LeaderType), 0) * 100) / s.N ELSE 0 END, s.K, s.LeaderType
  LIMIT 1;

CREATE TABLE IF NOT EXISTS LShufWork_Held (LeaderType TEXT, PieceId TEXT, FromLeader TEXT, Kind TEXT, BI INTEGER, IsRest INTEGER, SortIndex INTEGER, PRIMARY KEY (LeaderType, PieceId));
DELETE FROM LShufWork_Held;
  SELECT d.LeaderType, d.PieceId, d.FromLeader, p.Kind, p.BI, 0
  FROM LShufWork_Dealt d JOIN LShufWork_Pc p ON p.PieceId = d.PieceId WHERE d.LeaderType IS NOT NULL;
  SELECT LeaderType, LeaderType || '__REST', LeaderType, 'remainder', 0, 1 FROM LShufWork_Shape WHERE Whole = 0 AND HasRest = 1;
UPDATE LShufWork_Held SET SortIndex = (SELECT COUNT(*) FROM LShufWork_Held o WHERE o.LeaderType = LShufWork_Held.LeaderType AND (o.IsRest < LShufWork_Held.IsRest OR (o.IsRest = LShufWork_Held.IsRest AND (o.FromLeader < LShufWork_Held.FromLeader OR (o.FromLeader = LShufWork_Held.FromLeader AND (o.BI < LShufWork_Held.BI OR (o.BI = LShufWork_Held.BI AND (o.PieceId < LShufWork_Held.PieceId)))))))) WHERE 1 = 1;
CREATE TABLE IF NOT EXISTS LShufWork_Flow (Receiver TEXT, Giver TEXT, C INTEGER, V INTEGER, PRIMARY KEY (Receiver, Giver));
DELETE FROM LShufWork_Flow;
  FROM LShufWork_Dealt WHERE LeaderType IS NOT NULL GROUP BY LeaderType, FromLeader;
